-- 83 Siege Workshop: every engine is one prefab that is a hierarchy - a
-- catapult's frame, wheels, arm, bucket and stone come from one
-- spawn_prefab. The engines on show work: Entity.find_child finds each
-- one's arm, bucket stone, ballista head and bolt. The parade rolls out of
-- the gate, each engine's wheels turned by how far it has gone.
-- Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/83-siege-workshop.scene"
local KINDS = { SwCatapult = { -247.2, 7 }, SwBallista = { -253.6, 8 }, SwWagon = { -242.4, 9 }, SwRoyalCatapult = { -247.2, 9 } }
local ORDER = { "SwCatapult", "SwWagon", "SwBallista", "SwWagon", "SwRoyalCatapult", "SwWagon" }
local PENNANTS = { { 0.9, 0.2, 0.15 }, { 0.2, 0.45, 0.9 }, { 0.95, 0.8, 0.2 }, { 0.25, 0.7, 0.35 } }
local SCALE = 0.8       -- the parade's engines, parts and all
local R = 32 * SCALE   -- a wheel's radius
local COCKED, THROWN = 1.25, -0.3
local captions = true
local march = false
local status
local t = 0
local next_spawn = 0.5
local k = 0
local parade = {}
local shown = {}

local function rig(m)
    m.wl = Entity.find_child(m.e, "WheelL")
    m.wr = Entity.find_child(m.e, "WheelR")
    m.arm = Entity.find_child(m.e, "Arm")
    m.stone = Entity.find_child(m.e, "Arm/Bucket/Stone")
    m.head = Entity.find_child(m.e, "Head")
    m.bolt = Entity.find_child(m.e, "Head/Bolt")
    m.pennant = Entity.find_child(m.e, "Pennant")
    m.banner = Entity.find_child(m.e, "Banner")
    m.rigged = m.wl ~= nil
end

local function show()
    local parts = 0
    for _, m in ipairs(parade) do parts = parts + KINDS[m.kind][2] end
    UI.set_text(status, (march and "march" or "parade") .. ":  " .. #parade .. " engines,  "
        .. parts .. " entities from " .. #parade .. " spawn_prefab calls")
end

-- The throwing arm over one four-second cycle: thrown and settling, wound
-- back, held loaded, then let go.
local function arm_angle(c)
    if c < 0.5 then return THROWN + 0.08 * math.sin(c * 28) * (0.5 - c) end
    if c < 2.8 then
        local u = (c - 0.5) / 2.3
        u = u * u * (3 - 2 * u)
        return THROWN + (COCKED - THROWN) * u
    end
    if c < 3.6 then return COCKED end
    local u = math.min((c - 3.6) / 0.16, 1)
    return COCKED + (THROWN - COCKED) * u * u
end

local function work_catapult(m)
    local c = (t + m.phase) % 4.0
    if m.arm then Transform.set_rotation(m.arm, arm_angle(c)) end
    if m.stone then
        if c >= 3.72 and not m.fired then
            m.fired = true
            local x, y = Transform.get_world_position(m.stone)
            local shot = Entity.spawn_prefab("SwShot")
            Transform.set_position(shot, x, y)
            Physics.set_velocity(shot, 560, 520)
            Sprite.set_color(m.stone, 1, 1, 1, 0)
        elseif c > 1.2 and c < 3.0 and m.fired then
            m.fired = false
            Sprite.set_color(m.stone, 1, 1, 1, 1)   -- reloaded
        end
    end
end

local function work_ballista(m)
    local tilt = 0.12 + 0.1 * math.sin(t * 0.8)
    if m.head then Transform.set_rotation(m.head, tilt) end
    if not m.bolt then return end
    local c = (t + m.phase) % 3.0
    if c < 2.2 then
        local u = c / 2.2
        Transform.set_position(m.bolt, 10 - 40 * u * u, 9)
        if m.fired and c > 0.6 then
            m.fired = false
            Sprite.set_color(m.bolt, 1, 1, 1, 1)
        end
    elseif not m.fired then
        m.fired = true
        local x, y = Transform.get_world_position(m.bolt)
        local shot = Entity.spawn_prefab("SwBoltShot")
        Transform.set_position(shot, x, y)
        Transform.set_rotation(shot, tilt)
        Physics.set_velocity(shot, 1100 * math.cos(tilt), 1100 * math.sin(tilt))
        Sprite.set_color(m.bolt, 1, 1, 1, 0)
        Transform.set_position(m.bolt, 10, 9)
    end
end

function init(entity)
    status = Entity.find_by_name("Status")
    for i, name in ipairs({ "ShowCatapult", "ShowBallista", "ShowRoyal" }) do
        local m = { e = Entity.find_by_name(name), phase = i * 1.3 }
        rig(m)
        shown[#shown + 1] = m
    end
end

function update(entity, dt)
    nav.tick(SCENE)
    t = t + dt
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("Space") then march = not march end
    local speed = march and 170 or 90
    -- Roll out the next engine: one spawn_prefab, the whole machine.
    next_spawn = next_spawn - dt
    if next_spawn <= 0 then
        next_spawn = march and 1.8 or 3.4
        k = k + 1
        local kind = ORDER[(k - 1) % #ORDER + 1]
        local e = Entity.spawn_prefab(kind)
        local x = -780
        Transform.set_position(e, x, KINDS[kind][1])
        Transform.set_scale(e, SCALE, SCALE)
        parade[#parade + 1] = { e = e, kind = kind, x = x, x0 = x, n = k, age = 0 }
    end
    for i = #parade, 1, -1 do
        local m = parade[i]
        -- Its parts exist from the frame after the spawn is applied.
        m.age = m.age + 1
        if not m.rigged and m.age > 1 then
            rig(m)
            if m.pennant then
                local c = PENNANTS[(m.n - 1) % #PENNANTS + 1]
                Sprite.set_color(m.pennant, c[1], c[2], c[3], 1)
            end
        end
        m.x = m.x + speed * dt
        Transform.set_position(m.e, m.x, KINDS[m.kind][1])
        local roll = -(m.x - m.x0) / R
        if m.wl then Transform.set_rotation(m.wl, roll) end
        if m.wr then Transform.set_rotation(m.wr, roll + 0.4) end
        if m.pennant then Transform.set_rotation(m.pennant, 0.12 * math.sin(t * 6 + m.n)) end
        if m.banner then Transform.set_rotation(m.banner, 0.05 * math.sin(t * 2.5 + m.n)) end
        -- Off the far side: destroying the engine takes its parts.
        if m.x > 800 then
            Entity.destroy(m.e)
            table.remove(parade, i)
        end
    end
    for _, m in ipairs(shown) do
        if m.arm then work_catapult(m) end
        if m.head then work_ballista(m) end
        if m.banner then Transform.set_rotation(m.banner, 0.05 * math.sin(t * 1.7)) end
    end
    show()
end
